def compute(vars):
    value_2017 = vars["v1"]
    value_2016 = vars["v2"]

    if value_2016 == 0:
        return None

    decrease = value_2016 - value_2017
    decrease_percentage = (decrease / value_2016) * 100

    return {
        "value": decrease_percentage,
        "trace": {
            "value_2017": value_2017,
            "value_2016": value_2016,
            "decrease": decrease,
            "decrease_percentage": decrease_percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
